import { Link, Route, Router as WouterRouter, Switch, useLocation, useParams } from 'wouter';
import {
  getGetConventionQueryKey,
  getGetDashboardQueryKey,
  getListAttendeesQueryKey,
  getListConventionsQueryKey,
  getListFeedQueryKey,
  getListGroupsQueryKey,
  getListMessagesQueryKey,
  getListPhotoshootsQueryKey,
  getListChatsQueryKey,
  useCreateConvention,
  useCreateGroup,
  useCreateMessage,
  useCreatePhotoshoot,
  useCreatePost,
  useGetConvention,
  useGetDashboard,
  useJoinGroup,
  useListAttendees,
  useListChats,
  useListConventions,
  useListFeed,
  useListGroups,
  useListMessages,
  useListPhotoshoots,
  useMarkAttendance,
  useTogglePostLike,
} from '@workspace/api-client-react';
import type { Convention, ConventionDetail, Post, User } from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { useToast } from '@/hooks/use-toast';
import NotFound from '@/pages/not-found';

declare global {
  interface HTMLElement {
    showModal(): void;
    close(): void;
  }
}

const queryClient = new QueryClient();
const basePath = import.meta.env.BASE_URL.replace(/\/$/, '');
const configuredClerkKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY;
const clerkPubKey = configuredClerkKey ? publishableKeyFromHost(window.location.hostname, configuredClerkKey) : '';
const clerkProxyUrl = import.meta.env.VITE_CLERK_PROXY_URL;

function stripBase(path: string) {
  return basePath && path.startsWith(basePath) ? path.slice(basePath.length) || '/' : path;
}

const categories = ['All signals', 'Anime', 'Gaming', 'Comics', 'Fantasy', 'Movies', 'Conventions'];

function initials(name = 'Cosyn') {
  return name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase();
}

function Avatar({ user, size = 'md' }: { user?: Partial<User> | null; size?: 'sm' | 'md' | 'lg' }) {
  const sizes = { sm: 'h-8 w-8 text-[10px]', md: 'h-10 w-10 text-xs', lg: 'h-16 w-16 text-lg' };
  return user?.avatarUrl ? (
    <img data-testid={`img-avatar-${user.id ?? 'user'}`} src={user.avatarUrl} alt={user.username ?? 'avatar'} className={`${sizes[size]} shrink-0 rounded-full object-cover ring-2 ring-white/10`} />
  ) : (
    <div data-testid={`avatar-fallback-${user?.id ?? 'user'}`} className={`${sizes[size]} shrink-0 rounded-full bg-[linear-gradient(135deg,hsl(var(--primary)),hsl(var(--accent)))] flex items-center justify-center font-bold text-[hsl(var(--primary-foreground))]`}>
      {initials(user?.username)}
    </div>
  );
}

function Brand() {
  return <Link href="/" data-testid="link-brand" className="group flex items-center gap-2.5"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-[0_0_24px_hsl(var(--primary)/.2)] transition-transform group-hover:rotate-6"><Sparkles size={18} strokeWidth={2.5} /></div><span className="display-font text-xl font-extrabold tracking-tight">cosyn<span className="text-[hsl(var(--secondary))]">.</span></span></Link>;
}

function PageLoader() {
  return <div className="space-y-6 p-5 md:p-8"><div className="skeleton-shimmer h-10 w-48 rounded-lg" /><div className="grid gap-4 md:grid-cols-3"><div className="skeleton-shimmer h-48 rounded-2xl md:col-span-2" /><div className="skeleton-shimmer h-48 rounded-2xl" /></div><div className="skeleton-shimmer h-64 rounded-2xl" /></div>;
}

function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="glass-panel mx-auto my-10 max-w-md rounded-2xl p-8 text-center"><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-full bg-[hsl(var(--destructive)/.12)] text-[hsl(var(--destructive))]"><Radio size={21} /></div><h2 className="display-font text-xl font-bold">Signal lost</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">We could not reach the convention floor. Give it another try.</p>{retry && <button data-testid="button-retry" onClick={retry} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]"><RefreshCw size={15} /> Retry</button>}</div>;
}

function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.45)] px-6 py-12 text-center"><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-full bg-[hsl(var(--primary)/.1)] text-[hsl(var(--primary))]"><Sparkles size={20} /></div><h3 className="display-font text-lg font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">{body}</p>{action}</div>;
}

function Shell({ children }: { children: ReactNode }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [location] = useLocation();
  const nav = [{ href: '/', label: 'Home', icon: Compass }, { href: '/explore', label: 'Explore', icon: Search }, { href: '/chat', label: 'Chat', icon: MessageCircle }, { href: '/profile', label: 'My profile', icon: UserRound }];
  return <div className="noise-overlay min-h-[100dvh] bg-background">
    <aside className={`fixed inset-y-0 left-0 z-50 flex w-[248px] flex-col border-r border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar)/.96)] px-5 py-6 backdrop-blur-xl transition-transform duration-300 md:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="flex items-center justify-between"><Brand /><button data-testid="button-close-menu" className="text-[hsl(var(--muted-foreground))] md:hidden" onClick={() => setMobileOpen(false)}><X size={20} /></button></div>
      <div className="mt-10"><p className="mono-font mb-3 text-[10px] uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">Your orbit</p><nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMobileOpen(false)} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold transition-colors ${location === href ? 'bg-[hsl(var(--primary)/.13)] text-[hsl(var(--primary))]' : 'text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted)/.8)] hover:text-foreground'}`}><Icon size={17} />{label}{label === 'Chat' && <span className="ml-auto h-2 w-2 rounded-full bg-[hsl(var(--accent))]" />}</Link>)}</nav></div>
      <div className="mt-auto rounded-2xl border border-[hsl(var(--border))] bg-[linear-gradient(145deg,hsl(245_100%_72%/.13),hsl(195_100%_69%/.05))] p-4"><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">Before the doors</p><p className="mt-2 text-sm font-semibold leading-5">Find your people before you find the venue.</p><Link href="/explore" data-testid="link-sidebar-explore" className="mt-4 flex items-center gap-1 text-xs font-bold text-[hsl(var(--primary))]">Browse conventions <ArrowRight size={13} /></Link></div>
    </aside>
    {mobileOpen && <button aria-label="Close navigation" data-testid="button-menu-backdrop" onClick={() => setMobileOpen(false)} className="fixed inset-0 z-40 bg-black/60 md:hidden" />}
    <main className="md:pl-[248px]"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-[hsl(var(--border)/.7)] bg-[hsl(var(--background)/.82)] px-5 backdrop-blur-xl md:px-8"><div className="flex items-center gap-3"><button data-testid="button-open-menu" className="text-[hsl(var(--muted-foreground))] md:hidden" onClick={() => setMobileOpen(true)}><Menu size={21} /></button><div className="hidden text-sm text-[hsl(var(--muted-foreground))] sm:block">{location === '/' ? 'Your community, in motion' : location.slice(1).replaceAll('/', ' / ')}</div></div><div className="flex items-center gap-3"><Link href="/explore" data-testid="link-header-search" className="grid h-9 w-9 place-items-center rounded-xl border border-[hsl(var(--border))] text-[hsl(var(--muted-foreground))] hover:text-foreground"><Search size={17} /></Link><Link href="/profile" data-testid="link-header-profile" className="grid h-9 w-9 place-items-center rounded-xl bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><UserRound size={16} /></Link></div></header>{children}</main>
  </div>;
}

function Landing() {
  const [search, setSearch] = useState('');
  const { isLoaded, isSignedIn } = useAuth();
  const { data, isLoading, isError } = useGetDashboard({ query: { enabled: isLoaded && Boolean(isSignedIn), queryKey: getGetDashboardQueryKey() } });
  if (!isLoaded) return <PageLoader />;
  if (!isSignedIn) return <LandingPublic search={search} setSearch={setSearch} />;
  if (isLoading) return <PageLoader />;
  if (isError || !data) return <LandingPublic search={search} setSearch={setSearch} />;
  return <DashboardWithFeed dashboard={data} />;
}

function DashboardWithFeed({ dashboard }: { dashboard: { user: User; trending: Convention[]; featured: Convention[]; upcoming: Convention[]; feed: Post[] } }) {
  const { data: liveFeed = [] } = useListFeed({ query: { queryKey: getListFeedQueryKey() } });
  return <DashboardView dashboard={{ ...dashboard, feed: liveFeed.length ? liveFeed : dashboard.feed }} />;
}

function LandingPublic({ search, setSearch }: { search: string; setSearch: (v: string) => void }) {
  return <div className="mx-auto max-w-[1400px] px-5 py-8 md:px-10 md:py-12"><section className="hairline-grid relative overflow-hidden rounded-[2rem] border border-[hsl(var(--border))] bg-[radial-gradient(circle_at_78%_20%,hsl(309_91%_71%/.18),transparent_20rem),linear-gradient(125deg,hsl(247_35%_10%),hsl(249_45%_8%))] px-6 py-12 md:px-14 md:py-20"><div className="absolute -right-24 -top-24 h-72 w-72 rounded-full border border-[hsl(var(--primary)/.2)] md:h-96 md:w-96" /><div className="absolute -right-10 top-14 h-52 w-52 rounded-full border border-[hsl(var(--secondary)/.18)]" /><div className="relative max-w-3xl"><p className="mono-font mb-5 flex items-center gap-2 text-[10px] uppercase tracking-[.22em] text-[hsl(var(--secondary))]"><span className="h-2 w-2 animate-pulse rounded-full bg-[hsl(var(--accent))]" />The fandom social layer</p><h1 className="display-font max-w-3xl text-5xl font-extrabold leading-[.98] tracking-[-.04em] md:text-8xl">Your people are<br /><span className="text-[hsl(var(--primary))]">already gathering.</span></h1><p className="mt-7 max-w-xl text-base leading-7 text-[hsl(var(--muted-foreground))] md:text-lg">Cosyn is where convention plans, cosplay progress, and late-night fandom energy find a home.</p><div className="mt-9 flex flex-col gap-3 sm:flex-row"><Link href="/explore" data-testid="link-hero-explore" className="inline-flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-5 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))] transition-transform hover:-translate-y-0.5">Explore the orbit <ArrowRight size={16} /></Link><Link href="/sign-up" data-testid="link-hero-signup" className="inline-flex items-center justify-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card)/.5)] px-5 py-3 text-sm font-bold hover:border-[hsl(var(--primary)/.6)]">Make your profile</Link></div></div><div className="relative mt-12 max-w-xl md:absolute md:bottom-12 md:right-12 md:mt-0"><label className="mono-font mb-2 block text-[10px] uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">Find your next signal</label><div className="flex items-center rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--background)/.75)] p-2 shadow-xl"><Search className="ml-2 text-[hsl(var(--primary))]" size={18} /><input data-testid="input-landing-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Try Anime Expo, London..." className="min-w-0 flex-1 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-[hsl(var(--muted-foreground))]" /><Link href={`/explore${search ? `?search=${encodeURIComponent(search)}` : ''}`} data-testid="button-landing-search" className="rounded-xl bg-[hsl(var(--secondary))] px-3 py-2 text-xs font-bold text-[hsl(var(--secondary-foreground))]">Search</Link></div></div></section><div className="grid gap-4 py-10 sm:grid-cols-3"><Stat label="conventions indexed" value="2,846" /><Stat label="active fan circles" value="18.7k" /><Stat label="cosplay plans shared" value="42.3k" /></div></div>;
}

function Stat({ label, value }: { label: string; value: string }) {
  return <div className="border-l-2 border-[hsl(var(--primary)/.5)] pl-4"><p className="display-font text-2xl font-bold">{value}</p><p className="mono-font mt-1 text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">{label}</p></div>;
}

function DashboardView({ dashboard }: { dashboard: { user: User; trending: Convention[]; featured: Convention[]; upcoming: Convention[]; feed: Post[] } }) {
  return <div className="mx-auto max-w-[1400px] px-5 py-7 md:px-10 md:py-10"><div className="animate-rise flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mono-font text-[10px] uppercase tracking-[.2em] text-[hsl(var(--secondary))]">Tuesday, 18 June</p><h1 data-testid="text-dashboard-greeting" className="display-font mt-2 text-4xl font-extrabold tracking-[-.035em] md:text-6xl">Hey, {dashboard.user.username}.</h1><p className="mt-2 text-[hsl(var(--muted-foreground))]">The floor is moving. Here is your view from orbit.</p></div><Link href="/explore" data-testid="link-dashboard-explore" className="inline-flex w-fit items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-4 py-2.5 text-sm font-bold hover:border-[hsl(var(--primary)/.6)]">Discover a convention <ArrowRight size={15} /></Link></div><section className="mt-10 grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><div className="animate-rise animate-rise-1 overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] px-5 py-4"><div><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--accent))]">In your radius</p><h2 className="display-font mt-1 text-xl font-bold">Trending conventions</h2></div><Link href="/explore" data-testid="link-trending-see-all" className="text-xs font-bold text-[hsl(var(--primary))]">See all</Link></div><div className="divide-y divide-[hsl(var(--border))]">{dashboard.trending.slice(0, 3).map((convention) => <ConventionRow key={convention.id} convention={convention} />)}</div></div><div className="animate-rise animate-rise-2 rounded-2xl border border-[hsl(var(--border))] bg-[linear-gradient(145deg,hsl(247_35%_12%),hsl(248_45%_8%))] p-5"><div className="flex items-center justify-between"><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">Your stats</p><Zap size={17} className="text-[hsl(var(--accent))]" /></div><div className="mt-7 flex items-end gap-3"><Avatar user={dashboard.user} size="lg" /><div><p className="text-2xl font-bold">{dashboard.user.conventionsAttended}</p><p className="text-xs text-[hsl(var(--muted-foreground))]">conventions attended</p></div></div><div className="mt-7 grid grid-cols-2 gap-3"><MiniStat label="friends" value={dashboard.user.friendsCount} /><MiniStat label="cosplay posts" value={dashboard.user.cosplayPosts} /></div><Link href="/profile" data-testid="link-view-profile" className="mt-5 flex items-center justify-between rounded-xl bg-[hsl(var(--muted)/.8)] px-3 py-2.5 text-xs font-bold">View your profile <ArrowRight size={14} className="text-[hsl(var(--primary))]" /></Link></div></section><section className="mt-10"><SectionHeader eyebrow="On the horizon" title="Your upcoming floor plans" action={<Link href="/explore" data-testid="link-upcoming-see-all" className="text-xs font-bold text-[hsl(var(--primary))]">Browse more</Link>} />{dashboard.upcoming.length ? <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">{dashboard.upcoming.slice(0, 3).map((c) => <ConventionCard key={c.id} convention={c} />)}</div> : <EmptyState title="Your calendar is quiet" body="Mark a convention as attending and your floor plans will appear here." action={<Link href="/explore" data-testid="link-empty-explore" className="mt-5 inline-flex rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--primary-foreground))]">Explore conventions</Link>} />}</section><Feed posts={dashboard.feed} /></div>;
}

function MiniStat({ label, value }: { label: string; value: number }) { return <div className="rounded-xl bg-[hsl(var(--muted)/.75)] p-3"><p className="text-lg font-bold">{value}</p><p className="mono-font text-[9px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">{label}</p></div>; }
function SectionHeader({ eyebrow, title, action }: { eyebrow: string; title: string; action?: React.ReactNode }) { return <div className="flex items-end justify-between"><div><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">{eyebrow}</p><h2 className="display-font mt-1 text-2xl font-bold">{title}</h2></div>{action}</div>; }
function ConventionRow({ convention }: { convention: Convention }) { return <Link href={`/conventions/${convention.id}`} data-testid={`row-convention-${convention.id}`} className="flex items-center gap-4 px-5 py-4 transition-colors hover:bg-[hsl(var(--muted)/.5)]"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-[linear-gradient(135deg,hsl(var(--primary)/.22),hsl(var(--secondary)/.15))] text-[hsl(var(--primary))]"><CalendarDays size={18} /></div><div className="min-w-0 flex-1"><p className="truncate font-bold">{convention.name}</p><p className="mt-1 flex items-center gap-1 text-xs text-[hsl(var(--muted-foreground))]"><MapPin size={12} />{convention.city}, {convention.country} <span className="mx-1 text-[hsl(var(--border))]">/</span> {convention.category}</p></div><div className="hidden text-right sm:block"><p className="mono-font text-[10px] text-[hsl(var(--secondary))]">{dateLabel(convention.startDate)}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{convention.attendeeCount.toLocaleString()} going</p></div><ChevronRight className="text-[hsl(var(--muted-foreground))]" size={16} /></Link>; }
function ConventionCard({ convention, featured = false }: { convention: Convention; featured?: boolean }) { return <Link href={`/conventions/${convention.id}`} data-testid={`card-convention-${convention.id}`} className={`group relative overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] transition-transform duration-300 hover:-translate-y-1 hover:border-[hsl(var(--primary)/.6)] ${featured ? 'md:col-span-2' : ''}`}><div className="relative h-36 overflow-hidden bg-[linear-gradient(120deg,hsl(257_55%_28%),hsl(198_72%_22%))]">{convention.bannerUrl ? <img src={convention.bannerUrl} alt="" className="h-full w-full object-cover opacity-70 transition-transform duration-500 group-hover:scale-105" /> : <div className="hairline-grid h-full w-full" />}<div className="absolute inset-0 bg-gradient-to-t from-[hsl(var(--card))] to-transparent" /><span className="absolute left-4 top-4 rounded-md bg-[hsl(var(--background)/.72)] px-2 py-1 mono-font text-[9px] uppercase tracking-wider text-[hsl(var(--secondary))]">{convention.category}</span></div><div className="p-4"><div className="flex items-start justify-between gap-3"><div><h3 className="display-font font-bold leading-tight">{convention.name}</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{convention.venue} · {convention.city}</p></div><span className="mono-font shrink-0 text-[10px] text-[hsl(var(--primary))]">{dateLabel(convention.startDate)}</span></div><div className="mt-4 flex items-center gap-4 text-xs text-[hsl(var(--muted-foreground))]"><span className="flex items-center gap-1"><Users size={13} />{convention.attendeeCount.toLocaleString()}</span><span className="flex items-center gap-1"><MapPin size={13} />{convention.country}</span></div></div></Link>; }
function dateLabel(date: string) { const d = new Date(date); return Number.isNaN(d.valueOf()) ? date : d.toLocaleDateString('en', { month: 'short', day: 'numeric' }); }

function Feed({ posts }: { posts: Post[] }) { const qc = useQueryClient(); const like = useTogglePostLike(); const { toast } = useToast(); const [body, setBody] = useState(''); const create = useCreatePost(); return <section className="mt-10 max-w-3xl"><SectionHeader eyebrow="Community frequency" title="From the feed" /><div className="mt-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4"><div className="flex gap-3"><Avatar user={null} /><textarea data-testid="input-create-post" value={body} onChange={(e) => setBody(e.target.value)} placeholder="Share a build update, a convention find, a small win..." className="min-h-10 flex-1 resize-none bg-transparent py-2 text-sm outline-none placeholder:text-[hsl(var(--muted-foreground))]" /></div><div className="mt-3 flex justify-end"><button data-testid="button-create-post" disabled={!body.trim() || create.isPending} onClick={() => create.mutate({ data: { body: body.trim() } }, { onSuccess: () => { setBody(''); qc.invalidateQueries({ queryKey: getListFeedQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); toast({ title: 'Posted to the orbit' }); } })} className="rounded-xl bg-[hsl(var(--primary))] px-4 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))] disabled:opacity-40">{create.isPending ? 'Sending...' : 'Post update'}</button></div></div><div className="mt-4 space-y-3">{posts.length ? posts.slice(0, 5).map((post) => <article key={post.id} data-testid={`card-post-${post.id}`} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex items-center gap-3"><Avatar user={post.author} size="sm" /><div><p className="text-sm font-bold">{post.author.username}</p><p className="mono-font text-[9px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">{timeAgo(post.createdAt)}</p></div></div><p className="mt-4 text-sm leading-6 text-[hsl(var(--foreground)/.88)]">{post.body}</p>{post.imageUrl && <img src={post.imageUrl} alt="" className="mt-4 max-h-72 w-full rounded-xl object-cover" />}<div className="mt-4 flex items-center gap-5 text-xs text-[hsl(var(--muted-foreground))]"><button data-testid={`button-like-post-${post.id}`} onClick={() => like.mutate({ id: post.id }, { onSuccess: (updated) => { qc.setQueryData(getListFeedQueryKey(), (old: Post[] | undefined) => old?.map((p) => p.id === updated.id ? updated : p)); } })} className={`flex items-center gap-1.5 transition-colors hover:text-[hsl(var(--accent))] ${post.likedByMe ? 'text-[hsl(var(--accent))]' : ''}`}><Heart size={15} fill={post.likedByMe ? 'currentColor' : 'none'} />{post.likes}</button><span className="flex items-center gap-1.5"><MessageCircle size={15} />{post.comments}</span></div></article>) : <EmptyState title="Your feed is waiting" body="Be the first to share what you are making, watching, or planning." />}</div></section>; }
function timeAgo(date: string) { const diff = Math.max(1, Date.now() - new Date(date).valueOf()); const mins = Math.floor(diff / 60000); return mins < 60 ? `${mins}m ago` : mins < 1440 ? `${Math.floor(mins / 60)}h ago` : `${Math.floor(mins / 1440)}d ago`; }

function Explore() { const params = new URLSearchParams(window.location.search); const [search, setSearch] = useState(params.get('search') ?? ''); const [category, setCategory] = useState(''); const [country, setCountry] = useState(''); const listParams = useMemo(() => ({ search: search || undefined, category: category || undefined, country: country || undefined }), [search, category, country]); const { data, isLoading, isError, refetch } = useListConventions(listParams, { query: { queryKey: getListConventionsQueryKey(listParams) } }); return <div className="mx-auto max-w-[1400px] px-5 py-8 md:px-10 md:py-10"><div className="animate-rise flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><p className="mono-font text-[10px] uppercase tracking-[.2em] text-[hsl(var(--secondary))]">The convention radar</p><h1 className="display-font mt-2 text-4xl font-extrabold tracking-[-.04em] md:text-6xl">Find your next <span className="text-[hsl(var(--primary))]">room.</span></h1><p className="mt-2 max-w-xl text-[hsl(var(--muted-foreground))]">Search the events where fandom turns into real plans.</p></div><button data-testid="button-create-convention" className="inline-flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]" onClick={() => document.getElementById('create-convention')?.showModal()}><Plus size={16} /> Add a convention</button></div><div className="mt-8 flex flex-col gap-3 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card)/.7)] p-3 md:flex-row"><div className="flex flex-1 items-center gap-2 rounded-xl bg-[hsl(var(--muted)/.8)] px-3"><Search size={17} className="text-[hsl(var(--primary))]" /><input data-testid="input-convention-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by event, city, or country" className="w-full bg-transparent py-3 text-sm outline-none placeholder:text-[hsl(var(--muted-foreground))]" /></div><div className="flex gap-2 overflow-x-auto">{categories.map((item) => <button key={item} data-testid={`button-filter-${item.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setCategory(item === 'All signals' ? '' : item.replace('Conventions', ''))} className={`whitespace-nowrap rounded-xl px-3 py-2 text-xs font-bold transition-colors ${((item === 'All signals' && !category) || item === category) ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))] hover:text-foreground'}`}>{item}</button>)}</div></div><div className="mt-8 flex items-center justify-between"><p className="text-sm text-[hsl(var(--muted-foreground))]">{data?.length ?? 0} signals found</p><button data-testid="button-country-filter" onClick={() => setCountry(country ? '' : 'United States')} className={`flex items-center gap-2 text-xs font-bold ${country ? 'text-[hsl(var(--secondary))]' : 'text-[hsl(var(--muted-foreground))]'}`}><SlidersHorizontal size={14} /> {country || 'All locations'}</button></div>{isLoading ? <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">{[1, 2, 3].map((i) => <div key={i} className="skeleton-shimmer h-64 rounded-2xl" />)}</div> : isError ? <ErrorState retry={refetch} /> : data?.length ? <div className="mt-4 grid gap-4 md:grid-cols-2 lg:grid-cols-3">{data.map((c) => <ConventionCard key={c.id} convention={c} />)}</div> : <div className="mt-4"><EmptyState title="No conventions on this frequency" body="Try a broader search or be the person who adds the next one." /></div>}<CreateConventionDialog /></div>; }

function CreateConventionDialog() { const qc = useQueryClient(); const { toast } = useToast(); const create = useCreateConvention(); const [form, setForm] = useState({ name: '', city: '', country: '', venue: '', address: '', startDate: '', endDate: '', category: 'Anime', description: '', bannerUrl: '' }); const set = (key: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setForm({ ...form, [key]: e.target.value }); return <dialog id="create-convention" className="w-[min(92vw,560px)] rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-0 text-foreground backdrop:bg-black/70"><form method="dialog" onSubmit={(e) => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListConventionsQueryKey() }); toast({ title: 'Convention added to the radar' }); document.getElementById('create-convention')?.close(); } }); }} className="p-6"><div className="flex items-start justify-between"><div><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">New signal</p><h2 className="display-font mt-1 text-2xl font-bold">Add a convention</h2></div><button type="button" data-testid="button-close-create-convention" onClick={() => document.getElementById('create-convention')?.close()}><X size={19} /></button></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{[['name', 'Event name'], ['city', 'City'], ['country', 'Country'], ['venue', 'Venue'], ['address', 'Address'], ['category', 'Category'], ['startDate', 'Start date'], ['endDate', 'End date']].map(([key, label]) => <label key={key} className="text-xs font-semibold text-[hsl(var(--muted-foreground))]">{label}<input required={['name', 'city', 'country'].includes(key)} type={key.includes('Date') ? 'date' : 'text'} value={form[key as keyof typeof form]} onChange={set(key as keyof typeof form)} data-testid={`input-create-${key}`} className="mt-1.5 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted)/.65)] px-3 py-2.5 text-sm text-foreground outline-none focus:border-[hsl(var(--primary))]" /></label>)}</div><label className="mt-3 block text-xs font-semibold text-[hsl(var(--muted-foreground))]">Description<textarea value={form.description} onChange={set('description')} data-testid="input-create-description" className="mt-1.5 min-h-20 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted)/.65)] px-3 py-2.5 text-sm outline-none focus:border-[hsl(var(--primary))]" /></label><button disabled={create.isPending} data-testid="button-submit-convention" className="mt-5 w-full rounded-xl bg-[hsl(var(--primary))] py-3 text-sm font-bold text-[hsl(var(--primary-foreground))] disabled:opacity-50">{create.isPending ? 'Adding...' : 'Add to the radar'}</button></form></dialog>; }

function ConventionDetailPage() { const { id } = useParams<{ id: string }>(); const conventionId = Number(id); const { data, isLoading, isError, refetch } = useGetConvention(conventionId, { query: { queryKey: getGetConventionQueryKey(conventionId) } }); if (isLoading) return <PageLoader />; if (isError || !data) return <ErrorState retry={refetch} />; return <DetailView detail={data} />; }
function DetailView({ detail }: { detail: ConventionDetail }) { const qc = useQueryClient(); const { toast } = useToast(); const attendance = useMarkAttendance(); const { data: attendees, isLoading: attendeesLoading } = useListAttendees(detail.id, { query: { queryKey: getListAttendeesQueryKey(detail.id) } }); const { data: groups = [] } = useListGroups({ conventionId: detail.id }, { query: { queryKey: getListGroupsQueryKey({ conventionId: detail.id }) } }); const { data: photoshoots = [] } = useListPhotoshoots({ conventionId: detail.id }, { query: { queryKey: getListPhotoshootsQueryKey({ conventionId: detail.id }) } }); const [tab, setTab] = useState<'overview' | 'people' | 'groups' | 'photos'>('overview'); const join = (e: React.MouseEvent) => { e.preventDefault(); attendance.mutate({ id: detail.id, data: {} }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetConventionQueryKey(detail.id) }); qc.invalidateQueries({ queryKey: getListAttendeesQueryKey(detail.id) }); toast({ title: `You are going to ${detail.name}` }); } }); }; return <div className="mx-auto max-w-[1400px] px-5 py-7 md:px-10 md:py-10"><div className="relative overflow-hidden rounded-[2rem] border border-[hsl(var(--border))] bg-[linear-gradient(120deg,hsl(257_55%_23%),hsl(198_72%_18%))] p-6 md:p-10">{detail.bannerUrl && <img src={detail.bannerUrl} alt="" className="absolute inset-0 h-full w-full object-cover opacity-25 mix-blend-screen" />}<div className="relative max-w-3xl"><Link href="/explore" data-testid="link-back-explore" className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">← Convention radar</Link><div className="mt-12 flex flex-col gap-6 md:flex-row md:items-end md:justify-between"><div><span className="rounded-md bg-[hsl(var(--background)/.45)] px-2 py-1 mono-font text-[9px] uppercase tracking-wider text-[hsl(var(--accent))]">{detail.category}</span><h1 data-testid="text-convention-name" className="display-font mt-4 text-4xl font-extrabold leading-none tracking-[-.04em] md:text-7xl">{detail.name}</h1><p className="mt-4 flex items-center gap-2 text-sm text-[hsl(var(--foreground)/.72)]"><MapPin size={15} /> {detail.city}, {detail.country} · {detail.venue}</p></div><button data-testid="button-mark-attending" onClick={join} disabled={attendance.isPending || detail.isAttending} className={`inline-flex items-center justify-center gap-2 rounded-xl px-5 py-3 text-sm font-bold ${detail.isAttending ? 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}>{detail.isAttending ? <Check size={16} /> : <CalendarDays size={16} />}{detail.isAttending ? 'You are going' : attendance.isPending ? 'Joining...' : 'I am going'}</button></div></div></div><div className="mt-6 flex gap-2 overflow-x-auto border-b border-[hsl(var(--border))]">{[['overview', 'Overview'], ['people', 'Attendees'], ['groups', 'Cosplay groups'], ['photos', 'Photoshoots']].map(([value, label]) => <button key={value} data-testid={`button-detail-tab-${value}`} onClick={() => setTab(value as typeof tab)} className={`whitespace-nowrap border-b-2 px-3 py-3 text-sm font-bold ${tab === value ? 'border-[hsl(var(--primary))] text-[hsl(var(--primary))]' : 'border-transparent text-[hsl(var(--muted-foreground))]'}`}>{label}</button>)}</div>{tab === 'overview' && <div className="mt-8 grid gap-6 lg:grid-cols-[1.3fr_.7fr]"><div><p className="max-w-2xl text-base leading-8 text-[hsl(var(--foreground)/.8)]">{detail.description || 'The gathering point for people who make, watch, play, and obsess together.'}</p><div className="mt-7 grid gap-3 sm:grid-cols-3"><DetailMetric icon={CalendarDays} label="Dates" value={`${dateLabel(detail.startDate)} — ${dateLabel(detail.endDate)}`} /><DetailMetric icon={Users} label="Attendees" value={detail.attendeeCount.toLocaleString()} /><DetailMetric icon={MapPin} label="Venue" value={detail.venue} /></div></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">Live room</p><h3 className="display-font mt-2 text-xl font-bold">{detail.chat.name}</h3><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{detail.chat.lastMessage}</p><div className="mt-5 flex items-center justify-between text-xs text-[hsl(var(--muted-foreground))]"><span className="flex items-center gap-1"><Users size={14} /> {detail.chat.memberCount} members</span><Link href={`/chat?chat=${detail.chat.id}`} data-testid="link-open-convention-chat" className="flex items-center gap-1 font-bold text-[hsl(var(--primary))]">Open chat <ArrowRight size={14} /></Link></div></div></div>}{tab === 'people' && <People attendees={attendees ?? []} loading={attendeesLoading} />}{tab === 'groups' && <Groups conventionId={detail.id} groups={groups} />}{tab === 'photos' && <Photoshoots conventionId={detail.id} photoshoots={photoshoots} />}</div>; }
function DetailMetric({ icon: Icon, label, value }: { icon: typeof CalendarDays; label: string; value: string }) { return <div className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card)/.65)] p-4"><Icon size={16} className="text-[hsl(var(--primary))]" /><p className="mono-font mt-3 text-[9px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">{label}</p><p className="mt-1 text-sm font-bold">{value}</p></div>; }
function People({ attendees, loading }: { attendees: { id: number; username: string; avatarUrl: string; cosplayCharacter: string; fandom: string; progress: string }[]; loading: boolean }) { if (loading) return <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[1, 2, 3].map((i) => <div key={i} className="skeleton-shimmer h-24 rounded-2xl" />)}</div>; return attendees.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{attendees.map((a) => <div key={a.id} data-testid={`card-attendee-${a.id}`} className="flex items-center gap-3 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4"><Avatar user={{ id: a.id, username: a.username, avatarUrl: a.avatarUrl }} /><div className="min-w-0"><p className="truncate font-bold">{a.username}</p><p className="truncate text-xs text-[hsl(var(--primary))]">{a.cosplayCharacter || 'Civilian mode'}</p><p className="text-[11px] text-[hsl(var(--muted-foreground))]">{a.fandom || 'Fandom flexible'} · {a.progress || 'Planning'}</p></div></div>)}</div> : <EmptyState title="Be the first signal" body="No attendees have shared their plans yet." />; }
function Groups({ conventionId, groups }: { conventionId: number; groups: { id: number; name: string; description: string; characters: string; meetingPlace: string; meetingTime: string; memberCount: number; joined: boolean }[] }) { const qc = useQueryClient(); const join = useJoinGroup(); return <div><div className="mb-4 flex items-center justify-between"><p className="text-sm text-[hsl(var(--muted-foreground))]">Find the people building the same world.</p><button data-testid="button-create-group" onClick={() => document.getElementById('create-group')?.showModal()} className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold"><Plus size={14} /> Start a group</button></div><div className="grid gap-4 md:grid-cols-2">{groups.length ? groups.map((group) => <div key={group.id} data-testid={`card-group-${group.id}`} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex justify-between gap-3"><div><h3 className="display-font text-lg font-bold">{group.name}</h3><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{group.description}</p></div><span className="rounded-full bg-[hsl(var(--primary)/.1)] px-2 py-1 text-[10px] font-bold text-[hsl(var(--primary))]">{group.memberCount} members</span></div><p className="mt-4 text-xs text-[hsl(var(--muted-foreground))]">{group.characters} · {group.meetingPlace} · {group.meetingTime}</p><button data-testid={`button-join-group-${group.id}`} disabled={group.joined || join.isPending} onClick={() => join.mutate({ id: group.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListGroupsQueryKey({ conventionId }) }) })} className={`mt-5 w-full rounded-xl py-2.5 text-xs font-bold ${group.joined ? 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}>{group.joined ? 'Joined' : 'Join this group'}</button></div>) : <EmptyState title="No circles yet" body="Start the first cosplay circle for this convention." />}</div><CreateGroupDialog conventionId={conventionId} /></div>; }
function CreateGroupDialog({ conventionId }: { conventionId: number }) { const qc = useQueryClient(); const create = useCreateGroup(); const [form, setForm] = useState({ name: '', description: '', characters: '', meetingPlace: '', meetingTime: '' }); const update = (key: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setForm({ ...form, [key]: e.target.value }); return <dialog id="create-group" className="w-[min(92vw,500px)] rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-0 text-foreground backdrop:bg-black/70"><form method="dialog" onSubmit={(e) => { e.preventDefault(); create.mutate({ data: { ...form, conventionId } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListGroupsQueryKey({ conventionId }) }); document.getElementById('create-group')?.close(); } }); }} className="space-y-3 p-6"><div className="mb-5 flex items-start justify-between"><div><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">New circle</p><h2 className="display-font mt-1 text-2xl font-bold">Start a cosplay group</h2></div><button type="button" onClick={() => document.getElementById('create-group')?.close()}><X size={18} /></button></div>{[['name', 'Group name'], ['characters', 'Characters'], ['meetingPlace', 'Meeting place'], ['meetingTime', 'Meeting time']].map(([key, label]) => <input key={key} required value={form[key as keyof typeof form]} onChange={update(key as keyof typeof form)} placeholder={label} data-testid={`input-group-${key}`} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted))] px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" />)}<textarea required value={form.description} onChange={update('description')} placeholder="What is the energy of this circle?" data-testid="input-group-description" className="min-h-24 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted))] px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /><button disabled={create.isPending} data-testid="button-submit-group" className="w-full rounded-xl bg-[hsl(var(--primary))] py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]">Create group</button></form></dialog>; }
function Photoshoots({ conventionId, photoshoots }: { conventionId: number; photoshoots: { id: number; title: string; date: string; time: string; location: string; description: string; rsvpCount: number; joined: boolean }[] }) { const qc = useQueryClient(); const create = useCreatePhotoshoot(); const [rsvp, setRsvp] = useState<number[]>([]); return <div><div className="mb-4 flex items-center justify-between"><p className="text-sm text-[hsl(var(--muted-foreground))]">Make the memory before the shutter clicks.</p><button data-testid="button-create-photoshoot" onClick={() => document.getElementById('create-photoshoot')?.showModal()} className="flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold"><Plus size={14} /> Plan a shoot</button></div><div className="grid gap-4 md:grid-cols-2">{photoshoots.length ? photoshoots.map((photo) => <div key={photo.id} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex gap-4"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-[hsl(var(--accent)/.12)] text-[hsl(var(--accent))]"><Camera size={21} /></div><div><h3 className="display-font text-lg font-bold">{photo.title}</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{dateLabel(photo.date)} · {photo.time} · {photo.location}</p></div></div><p className="mt-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{photo.description}</p><button data-testid={`button-rsvp-photoshoot-${photo.id}`} onClick={() => { setRsvp([...rsvp, photo.id]); qc.invalidateQueries({ queryKey: getListPhotoshootsQueryKey({ conventionId }) }); }} disabled={photo.joined || rsvp.includes(photo.id)} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-[hsl(var(--muted))] py-2.5 text-xs font-bold">{photo.joined || rsvp.includes(photo.id) ? <Check size={14} /> : <CalendarDays size={14} />}{photo.joined || rsvp.includes(photo.id) ? 'RSVP confirmed' : `${photo.rsvpCount} RSVPs · Join shoot`}</button></div>) : <EmptyState title="No shoots scheduled" body="Plan a moment worth remembering." />}</div><dialog id="create-photoshoot" className="w-[min(92vw,500px)] rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-0 text-foreground backdrop:bg-black/70"><form method="dialog" onSubmit={(e) => { e.preventDefault(); const formData = new FormData(e.currentTarget); create.mutate({ data: { conventionId, title: String(formData.get('title')), date: String(formData.get('date')), time: String(formData.get('time')), location: String(formData.get('location')), description: String(formData.get('description')) } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListPhotoshootsQueryKey({ conventionId }) }); document.getElementById('create-photoshoot')?.close(); } }); }} className="space-y-3 p-6"><div className="mb-5 flex items-start justify-between"><div><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">New memory</p><h2 className="display-font mt-1 text-2xl font-bold">Plan a photoshoot</h2></div><button type="button" onClick={() => document.getElementById('create-photoshoot')?.close()}><X size={18} /></button></div>{[['title', 'Shoot title'], ['date', 'Date'], ['time', 'Time'], ['location', 'Location']].map(([key, label]) => <input required key={key} name={key} type={key === 'date' ? 'date' : key === 'time' ? 'time' : 'text'} placeholder={label} data-testid={`input-photoshoot-${key}`} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted))] px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" />)}<textarea required name="description" placeholder="What should people know?" data-testid="input-photoshoot-description" className="min-h-24 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted))] px-3 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /><button data-testid="button-submit-photoshoot" className="w-full rounded-xl bg-[hsl(var(--primary))] py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]">Create photoshoot</button></form></dialog></div>; }

function ChatPage() { const [selected, setSelected] = useState<number | null>(null); const [message, setMessage] = useState(''); const { data: chats = [], isLoading: chatsLoading, isError, refetch } = useListChats({ query: { queryKey: getListChatsQueryKey() } }); const chatParam = new URLSearchParams(window.location.search).get('chat'); const activeId = selected ?? (chatParam ? Number(chatParam) : chats[0]?.id ?? 0); const { data: messages = [], isLoading: messagesLoading } = useListMessages(activeId, { query: { queryKey: getListMessagesQueryKey(activeId), enabled: Boolean(activeId) } }); const qc = useQueryClient(); const send = useCreateMessage(); if (chatsLoading) return <PageLoader />; if (isError) return <ErrorState retry={refetch} />; return <div className="mx-auto flex min-h-[calc(100dvh-72px)] max-w-[1400px] flex-col md:flex-row"><aside className="w-full border-b border-[hsl(var(--border))] p-5 md:w-[320px] md:border-b-0 md:border-r md:p-7"><p className="mono-font text-[10px] uppercase tracking-[.2em] text-[hsl(var(--secondary))]">Open channels</p><h1 className="display-font mt-2 text-3xl font-bold">Chat</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">The plans happen here.</p><div className="mt-6 space-y-2">{chats.length ? chats.map((chat) => <button key={chat.id} data-testid={`button-select-chat-${chat.id}`} onClick={() => setSelected(chat.id)} className={`w-full rounded-xl p-3 text-left transition-colors ${activeId === chat.id ? 'bg-[hsl(var(--primary)/.13)]' : 'hover:bg-[hsl(var(--muted))]'}`}><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-[hsl(var(--secondary)/.12)] text-[hsl(var(--secondary))]"><MessageCircle size={16} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{chat.name}</p><p className="truncate text-xs text-[hsl(var(--muted-foreground))]">{chat.lastMessage}</p></div>{chat.unreadCount > 0 && <span className="rounded-full bg-[hsl(var(--accent))] px-1.5 py-0.5 text-[9px] font-bold text-[hsl(var(--accent-foreground))]">{chat.unreadCount}</span>}</div></button>) : <EmptyState title="No open channels" body="Attend a convention to enter its room." />}</div></aside><section className="flex min-h-[520px] flex-1 flex-col p-5 md:p-7">{activeId ? <><div className="flex items-center justify-between border-b border-[hsl(var(--border))] pb-5"><div><p className="mono-font text-[10px] uppercase tracking-wider text-[hsl(var(--secondary))]">Live room</p><h2 className="display-font mt-1 text-xl font-bold">{chats.find((chat) => chat.id === activeId)?.name ?? 'Convention channel'}</h2></div><span className="flex items-center gap-2 text-xs text-[hsl(var(--muted-foreground))]"><span className="h-2 w-2 animate-pulse rounded-full bg-[hsl(var(--accent))]" />{chats.find((chat) => chat.id === activeId)?.memberCount ?? 0} members</span></div><div className="flex-1 space-y-5 overflow-y-auto py-6">{messagesLoading ? [1, 2, 3].map((i) => <div key={i} className="skeleton-shimmer h-12 w-3/4 rounded-xl" />) : messages.length ? messages.map((msg) => <div key={msg.id} data-testid={`message-${msg.id}`} className="flex gap-3"><Avatar user={msg.author} size="sm" /><div><div className="flex items-baseline gap-2"><p className="text-sm font-bold">{msg.author.username}</p><p className="mono-font text-[9px] text-[hsl(var(--muted-foreground))]">{timeAgo(msg.createdAt)}</p></div><p className="mt-1 max-w-xl rounded-2xl rounded-tl-sm bg-[hsl(var(--muted))] px-4 py-3 text-sm leading-6">{msg.body}</p></div></div>) : <EmptyState title="Quiet channel" body="Drop the first message and set the tone." />}</div><form onSubmit={(e) => { e.preventDefault(); if (!message.trim()) return; send.mutate({ id: activeId, data: { body: message.trim() } }, { onSuccess: () => { setMessage(''); qc.invalidateQueries({ queryKey: getListMessagesQueryKey(activeId) }); qc.invalidateQueries({ queryKey: getListChatsQueryKey() }); } }); }} className="flex items-center gap-2 border-t border-[hsl(var(--border))] pt-4"><input data-testid="input-chat-message" value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Say something to the room..." className="flex-1 rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--muted)/.7)] px-4 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" /><button data-testid="button-send-message" disabled={!message.trim() || send.isPending} className="grid h-11 w-11 place-items-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] disabled:opacity-40"><Send size={17} /></button></form></> : <EmptyState title="Pick a channel" body="Your accessible convention rooms will show up here." />}</section></div>; }

function Profile() { const { data: dashboard, isLoading, isError, refetch } = useGetDashboard(); if (isLoading) return <PageLoader />; if (isError || !dashboard) return <ErrorState retry={refetch} />; const user = dashboard.user; return <div className="mx-auto max-w-[1100px] px-5 py-8 md:px-10 md:py-10"><div className="overflow-hidden rounded-[2rem] border border-[hsl(var(--border))] bg-[linear-gradient(135deg,hsl(257_55%_18%),hsl(248_45%_9%))]"><div className="hairline-grid h-28 md:h-40" /><div className="-mt-12 flex flex-col gap-5 px-6 pb-7 md:-mt-16 md:flex-row md:items-end md:px-10"><Avatar user={user} size="lg" /><div className="flex-1"><p className="mono-font text-[10px] uppercase tracking-[.18em] text-[hsl(var(--secondary))]">@{user.username}</p><h1 data-testid="text-profile-name" className="display-font mt-1 text-3xl font-extrabold">{user.username}</h1><p className="mt-2 max-w-xl text-sm leading-6 text-[hsl(var(--muted-foreground))]">{user.bio || 'Collecting worlds, one convention at a time.'}</p></div><button data-testid="button-edit-profile" className="rounded-xl border border-[hsl(var(--border))] px-4 py-2.5 text-xs font-bold hover:border-[hsl(var(--primary))]">Edit profile</button></div></div><div className="mt-6 grid gap-4 sm:grid-cols-3"><MiniStat label="friends" value={user.friendsCount} /><MiniStat label="attended" value={user.conventionsAttended} /><MiniStat label="cosplay posts" value={user.cosplayPosts} /></div><section className="mt-10"><SectionHeader eyebrow="Your route map" title="Upcoming conventions" /><div className="mt-4 grid gap-4 md:grid-cols-2">{dashboard.upcoming.length ? dashboard.upcoming.map((c) => <ConventionCard key={c.id} convention={c} />) : <EmptyState title="No plans pinned" body="Your next chapter starts in Explore." action={<Link href="/explore" data-testid="link-profile-explore" className="mt-5 inline-flex rounded-xl bg-[hsl(var(--primary))] px-4 py-2 text-sm font-bold text-[hsl(var(--primary-foreground))]">Open Explore</Link>} />}</div></section></div>; }

function AuthPage({ mode }: { mode: 'sign-in' | 'sign-up' }) { const Component = mode === 'sign-in' ? SignIn : SignUp; return clerkPubKey ? <div className="grid min-h-[100dvh] place-items-center bg-background p-5"><Component routing="path" path={`${basePath}/${mode}`} {...(mode === 'sign-in' ? { signUpUrl: `${basePath}/sign-up` } : { signInUrl: `${basePath}/sign-in` })} /></div> : <div className="grid min-h-[100dvh] place-items-center p-5"><div className="w-full max-w-md rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-8"><Brand /><h1 className="display-font mt-10 text-3xl font-bold">{mode === 'sign-in' ? 'Welcome back.' : 'Join the orbit.'}</h1><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Authentication is being connected for this environment.</p><Link href="/" data-testid="link-auth-home" className="mt-6 inline-flex rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]">Back to Cosyn</Link></div></div>; }

function AppRoutes() { return <Switch><Route path="/sign-in/*?" component={() => <AuthPage mode="sign-in" />} /><Route path="/sign-up/*?" component={() => <AuthPage mode="sign-up" />} /><Route path="/" component={Landing} /><Route path="/explore" component={Explore} /><Route path="/conventions/:id" component={ConventionDetailPage} /><Route path="/chat" component={ChatPage} /><Route path="/profile" component={Profile} /><Route component={NotFound} /></Switch>; }

function RoutedErrorBoundary({ children }: { children: React.ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }

function App() {
  const content = <QueryClientProvider client={queryClient}><TooltipProvider><RoutedErrorBoundary><Shell><AppRoutes /></Shell></RoutedErrorBoundary><Toaster /></TooltipProvider></QueryClientProvider>;
  if (!clerkPubKey) return <WouterRouter base={basePath}>{content}</WouterRouter>;
  const navigate = (to: string, replace = false) => {
    const nextPath = stripBase(to);
    if (replace) window.history.replaceState({}, '', nextPath);
    else window.history.pushState({}, '', nextPath);
    window.dispatchEvent(new PopStateEvent('popstate'));
  };
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} routerPush={(to) => navigate(to)} routerReplace={(to) => navigate(to, true)} appearance={{ variables: { colorPrimary: '#9a91ff', colorBackground: '#17152a', colorForeground: '#f4f2ff', colorMutedForeground: '#9b98ae', fontFamily: 'DM Sans, sans-serif', borderRadius: '0.85rem' }, elements: { cardBox: 'bg-[#17152a] border border-[#34304d] rounded-2xl', headerTitle: 'text-[#f4f2ff]', headerSubtitle: 'text-[#9b98ae]', formFieldLabel: 'text-[#f4f2ff]', formFieldInput: 'bg-[#24203b] border-[#443d65] text-[#f4f2ff]', formButtonPrimary: 'bg-[#9a91ff] text-[#100e1d]', footerActionLink: 'text-[#9a91ff]' } }}><WouterRouter base={basePath}>{content}</WouterRouter></ClerkProvider>;
}

export default App;